import {
  Card,
  Container,
  IconButton,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TablePagination,
  TableRow,
  Typography,
  TextField,
  Button,
  Box,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
  Alert
} from '@mui/material';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import { LocalizationProvider, DatePicker } from '@mui/x-date-pickers';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { sentenceCase } from 'change-case';
import { enqueueSnackbar } from 'notistack';
import { useEffect, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate } from 'react-router-dom';
import Iconify from '../../components/iconify';
import Label from '../../components/label';
import Scrollbar from '../../components/scrollbar';
import AuthService from '../../services/AuthService';
import HttpService from '../../services/HttpService';
import TransactionListHead from './TransactionListHead';

const TABLE_HEAD = [
  { id: 'id', label: 'Id', alignRight: false, firstColumn: true },
  { id: 'fromWallet', label: 'Sender', alignRight: false },
  { id: 'toWallet', label: 'Receiver', alignRight: false },
  { id: 'amount', label: 'Amount', alignRight: true },
  { id: 'category', label: 'Category', alignRight: false },
  { id: 'subcategory', label: 'Subcategory', alignRight: false },
  { id: 'description', label: 'Description', alignRight: false },
  { id: 'createdAt', label: 'Time of Transaction', alignRight: false },
  { id: 'type', label: 'Type', alignRight: false },
  { id: 'status', label: 'Status', alignRight: false },
  { id: '' },
];

const CATEGORIES = {
  'Food & Dining': ['Groceries', 'Restaurants', 'Fast Food'],
  'Transportation': ['Public Transit', 'Fuel', 'Car Maintenance'],
  'Shopping': ['Clothing', 'Electronics', 'Home Goods'],
  'Bills & Utilities': ['Electricity', 'Water', 'Internet'],
  'Healthcare': ['Doctor', 'Pharmacy', 'Insurance'],
  'Entertainment': ['Movies', 'Games', 'Sports'],
};

export default function Transaction() {
  const [open, setOpen] = useState(null);
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState([]);
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [data, setData] = useState([]);
  const navigate = useNavigate();

  // New states for enhanced features
  const [startDate, setStartDate] = useState(null);
  const [endDate, setEndDate] = useState(null);
  const [budget, setBudget] = useState('');
  const [monthlySpent, setMonthlySpent] = useState(0);
  const [selectedCategory, setSelectedCategory] = useState('');
  const [selectedSubcategory, setSelectedSubcategory] = useState('');
  const [categoryStats, setCategoryStats] = useState([]);

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    calculateMonthlySpent();
    generateCategoryStats();
  }, [data]);

  const handleOpenMenu = (event) => {
    setOpen(event.currentTarget);
  };

  const handleCloseMenu = () => {
    setOpen(null);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setPage(0);
    setRowsPerPage(parseInt(event.target.value, 10));
  };

  const handleCategoryChange = (event) => {
    setSelectedCategory(event.target.value);
    setSelectedSubcategory('');
  };

  const handleSubcategoryChange = (event) => {
    setSelectedSubcategory(event.target.value);
  };

  const handleBudgetChange = (event) => {
    const newBudget = event.target.value;
    setBudget(newBudget);
    checkBudgetExceed(monthlySpent, newBudget);
  };

  const checkBudgetExceed = (spent, budgetLimit) => {
    if (budgetLimit && spent > Number(budgetLimit)) {
      enqueueSnackbar('Warning: Monthly spending has exceeded budget!', { 
        variant: 'warning',
        autoHideDuration: 5000,
      });
    }
  };

  const calculateMonthlySpent = () => {
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();

    const monthlyTransactions = data.filter(transaction => {
      const transDate = new Date(transaction.createdAt);
      return transDate.getMonth() === currentMonth && 
             transDate.getFullYear() === currentYear;
    });

    const total = monthlyTransactions.reduce((sum, transaction) => 
      sum + Number(transaction.amount), 0
    );

    setMonthlySpent(total);
    if (budget) {
      checkBudgetExceed(total, budget);
    }
  };

  const generateCategoryStats = () => {
    const stats = Object.keys(CATEGORIES).map(category => ({
      name: category,
      amount: data
        .filter(t => t.category === category)
        .reduce((sum, t) => sum + Number(t.amount), 0)
    }));
    setCategoryStats(stats);
  };

  const handleGenerateReport = () => {
    if (!startDate || !endDate) {
      enqueueSnackbar('Please select both start and end dates', { variant: 'warning' });
      return;
    }

    const userId = AuthService.getCurrentUser()?.id;
    HttpService.getWithAuth(
      `/transactions/users/${userId}?startDate=${startDate.toISOString()}&endDate=${endDate.toISOString()}`
    )
      .then((response) => {
        setData(response.data.content);
        generateCategoryStats();
      })
      .catch((error) => handleError(error));
  };

  const fetchData = () => {
    const userId = AuthService.getCurrentUser()?.id;
    HttpService.getWithAuth(`/transactions/users/${userId}`)
      .then((response) => {
        setData(response.data.content);
      })
      .catch((error) => handleError(error));
  };

  const handleError = (error) => {
    if (error?.response?.status === 401) {
      navigate('/login');
    } else if (error.response?.data?.errors) {
      error.response?.data?.errors.map((e) => enqueueSnackbar(e.message, { variant: 'error' }));
    } else if (error.response?.data?.message) {
      enqueueSnackbar(error.response?.data?.message, { variant: 'error' });
    } else {
      enqueueSnackbar(error.message, { variant: 'error' });
    }
  };

  const emptyRows = page > 0 ? Math.max(0, (1 + page) * rowsPerPage - data.length) : 0;

  return (
    <LocalizationProvider dateAdapter={AdapterDateFns}>
      <Helmet>
        <title> Transactions | e-Transaction </title>
      </Helmet>
      <Container sx={{ minWidth: '100%' }}>
        <Stack direction="row" alignItems="center" justifyContent="space-between" mb={1}>
          <Typography variant="h4" gutterBottom>
            My Transactions
          </Typography>
        </Stack>

        {/* Budget Management */}
        <Card sx={{ p: 3, mb: 3 }}>
          <Stack spacing={3}>
            <Typography variant="h6">Budget Management</Typography>
            <Stack direction="row" spacing={3} alignItems="center">
              <TextField
                label="Monthly Budget"
                type="number"
                value={budget}
                onChange={handleBudgetChange}
                sx={{ width: 200 }}
              />
              <Typography>
                Monthly Spent: ${monthlySpent.toFixed(2)}
              </Typography>
              {budget && monthlySpent > Number(budget) && (
                <Alert severity="warning" sx={{ flex: 1 }}>
                  Budget Exceeded! (${(monthlySpent - Number(budget)).toFixed(2)} over budget)
                </Alert>
              )}
            </Stack>
          </Stack>
        </Card>

        {/* Report Generation */}
        <Card sx={{ p: 3, mb: 3 }}>
          <Stack spacing={3}>
            <Typography variant="h6">Generate Report</Typography>
            <Stack direction="row" spacing={3} alignItems="center">
              <DatePicker
                label="Start Date"
                value={startDate}
                onChange={setStartDate}
                renderInput={(params) => <TextField {...params} />}
              />
              <DatePicker
                label="End Date"
                value={endDate}
                onChange={setEndDate}
                renderInput={(params) => <TextField {...params} />}
              />
              <Button variant="contained" onClick={handleGenerateReport}>
                Generate Report
              </Button>
            </Stack>
          </Stack>
        </Card>

        {/* Category Management */}
        <Card sx={{ p: 3, mb: 3 }}>
          <Stack spacing={3}>
            <Typography variant="h6">Transaction Categories</Typography>
            <Stack direction="row" spacing={3}>
              <FormControl sx={{ minWidth: 200 }}>
                <InputLabel>Category</InputLabel>
                <Select value={selectedCategory} onChange={handleCategoryChange}>
                  {Object.keys(CATEGORIES).map((category) => (
                    <MenuItem key={category} value={category}>
                      {category}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
              <FormControl sx={{ minWidth: 200 }}>
                <InputLabel>Subcategory</InputLabel>
                <Select
                  value={selectedSubcategory}
                  onChange={handleSubcategoryChange}
                  disabled={!selectedCategory}
                >
                  {selectedCategory &&
                    CATEGORIES[selectedCategory].map((sub) => (
                      <MenuItem key={sub} value={sub}>
                        {sub}
                      </MenuItem>
                    ))}
                </Select>
              </FormControl>
            </Stack>
          </Stack>
        </Card>

        {/* Visualization */}
        <Card sx={{ p: 3, mb: 3 }}>
          <Typography variant="h6" gutterBottom>
            Spending by Category
          </Typography>
          <Box sx={{ width: '100%', height: 300 }}>
            <ResponsiveContainer>
              <BarChart data={categoryStats}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip />
                <Legend />
                <Bar dataKey="amount" fill="#8884d8" />
              </BarChart>
            </ResponsiveContainer>
          </Box>
        </Card>

        {/* Transactions Table */}
        <Card>
          <Scrollbar>
            <TableContainer sx={{ minWidth: 800 }}>
              <Table>
                <TransactionListHead headLabel={TABLE_HEAD} />
                <TableBody>
                  {data &&
                    data.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage).map((row) => {
                      const { id, amount, description, createdAt, fromWallet, toWallet, type, status } = row;
                      const selectedRecord = selected.indexOf(id) !== -1;
                      return (
                        <TableRow hover key={id} tabIndex={-1} role="checkbox" selected={selectedRecord}>
                          <TableCell align="left" sx={{ paddingLeft: 5 }}>
                            {id}
                          </TableCell>
                          <TableCell align="left">{`${fromWallet.user.firstName} ${fromWallet.user.lastName}`}</TableCell>
                          <TableCell align="left">{`${toWallet.user.firstName} ${toWallet.user.lastName}`}</TableCell>
                          <TableCell align="right">{amount}</TableCell>
                          <TableCell align="left">{row.category || 'Uncategorized'}</TableCell>
                          <TableCell align="left">{row.subcategory || '-'}</TableCell>
                          <TableCell align="left">{description}</TableCell>
                          <TableCell align="left">{createdAt}</TableCell>
                          <TableCell align="left">{type.name}</TableCell>
                          <TableCell align="left">
                            <Label color={status === 'SUCCESS' ? 'success' : 'warning'}>
                              {sentenceCase(status)}
                            </Label>
                          </TableCell>
                          <TableCell align="right" width="20">
                            <IconButton size="large" color="inherit" onClick={handleOpenMenu}>
                              <Iconify icon={'eva:more-vertical-fill'} />
                            </IconButton>
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  {emptyRows > 0 && (
                    <TableRow style={{ height: 53 * emptyRows }}>
                      <TableCell colSpan={6} />
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </Scrollbar>
          <TablePagination
            rowsPerPageOptions={[5, 10, 25]}
            component="div"
            count={data?.length > 0 ? data.length : 0}
            rowsPerPage={rowsPerPage}
            page={page}
            onPageChange={handleChangePage}
            onRowsPerPageChange={handleChangeRowsPerPage}
          />
        </Card>
      </Container>
    </LocalizationProvider>
  );
}
